@push('scripts')
<script>
(() => {
    let refreshTimer = null;
    let refreshing = false;
    let queued = false;

    const bindConversationCards = () => {
        const page = document.getElementById('chatPage');
        document.querySelectorAll('.conversation-card').forEach((card) => {
            card.addEventListener('click', () => page?.classList.add('conversation-open'));
        });
        const query = document.getElementById('conversationSearch')?.value.trim().toLowerCase() || '';
        document.querySelectorAll('.conversation-card').forEach((card) => {
            card.hidden = Boolean(query) && !card.dataset.conversationName.includes(query);
        });
    };

    const refreshChat = async () => {
        if (document.visibilityState !== 'visible') { queued = true; return; }
        if (refreshing) { queued = true; return; }
        refreshing = true;
        try {
            const response = await fetch(window.location.href, {
                headers: { Accept: 'text/html' },
                cache: 'no-store'
            });
            if (!response.ok) return;
            const parsed = new DOMParser().parseFromString(await response.text(), 'text/html');
            const currentList = document.getElementById('conversationList');
            const nextList = parsed.getElementById('conversationList');
            const currentMessages = document.getElementById('chatMessages');
            const nextMessages = parsed.getElementById('chatMessages');
            if (currentList && nextList) {
                const scrollTop = currentList.scrollTop;
                currentList.replaceWith(nextList);
                nextList.scrollTop = scrollTop;
                bindConversationCards();
            }
            if (currentMessages && nextMessages) {
                const wasAtBottom = currentMessages.scrollHeight - currentMessages.scrollTop - currentMessages.clientHeight < 80;
                currentMessages.replaceWith(nextMessages);
                if (wasAtBottom) nextMessages.scrollTop = nextMessages.scrollHeight;
            }
        } catch (_) {
            // Keep the inbox usable if a background refresh is unavailable.
        } finally {
            refreshing = false;
            if (queued) { queued = false; scheduleRefresh(); }
        }
    };

    const scheduleRefresh = () => {
        window.clearTimeout(refreshTimer);
        refreshTimer = window.setTimeout(refreshChat, 180);
    };
    const onSignal = (event) => {
        if (event.detail?.entity_type === 'chat') scheduleRefresh();
    };
    window.addEventListener('aqua:realtime', onSignal);
    window.addEventListener('aqua:chat-incoming', scheduleRefresh);
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible' && queued) scheduleRefresh();
    });
    bindConversationCards();
    window.addEventListener('beforeunload', () => {
        window.clearTimeout(refreshTimer);
        window.removeEventListener('aqua:realtime', onSignal);
        window.removeEventListener('aqua:chat-incoming', scheduleRefresh);
    }, { once: true });
})();
</script>
@endpush
